import fs from 'node:fs/promises';
import path from 'node:path';
import {load,readJSON,write,stats,esc,slug,root} from './lib.mjs';
import {buildIntelligence,DATASET_VERSION,CALCULATED_AT} from './intelligence.mjs';
import {buildSourceRegistry,buildKnowledgeGraph,factDisplay,sourceQuality,SCHEMA_VERSION} from './governance.mjs';

const {entities,taxonomy,semantic,definitions}=await load();
const rawRelationships=await readJSON('data/relationships/relationships.json');
const cfoTaxonomy=await readJSON('data/taxonomy/cfo.json');
const cfoGuides=await readJSON('data/guides/cfo.json');
const expansion=await readJSON('data/expansions/2026-08-supplied.json');
const resolutionV050=await readJSON('data/reconciliation-v050.json');
const s=stats(entities);
const intelligence=buildIntelligence(entities);
const sourceRegistry=buildSourceRegistry(entities);
const knowledgeGraph=buildKnowledgeGraph(entities,rawRelationships,sourceRegistry);
const sourceMetrics=sourceQuality(entities,sourceRegistry);
const byId=new Map(entities.map(entity=>[entity.id,entity]));
const relationsBySubject=Object.groupBy(knowledgeGraph.relationships,relationship=>relationship.subject_entity_id);
const derivedMetricCount=intelligence.market_maps.reduce((count,map)=>count+1+map.buckets.length,0)+intelligence.benchmarks.reduce((count,benchmark)=>count+(benchmark.metrics?.length||1),0);
for(const folder of ['entities','providers','formats','intelligence','industries'])await fs.rm(path.join(root,'docs',folder),{recursive:true,force:true});
const dimensions=['provider_types','community_formats','event_formats','intelligence_types','resource_types','executive_needs','topics','audiences'];
const vocab=new Map(Object.entries(semantic).flatMap(([dimension,items])=>items.map(item=>[`${dimension}:${item.id}`,item])));
const labels=(dimension,ids=[])=>ids.map(id=>vocab.get(`${dimension}:${id}`)?.label||id);
const q=value=>`"${String(value??'').replaceAll('"','""')}"`;
const cols=['id','name','slug','entity_type','website','cxo_roles','categories',...dimensions,'industries','geographies','verification_status','last_verified'];
const csv=[cols.join(','),...entities.map(entity=>cols.map(key=>q(Array.isArray(entity[key])?entity[key].join('|'):entity[key])).join(','))].join('\n')+'\n';

await write('data/exports/entities.json',JSON.stringify({schema_version:SCHEMA_VERSION,dataset_version:DATASET_VERSION,generated_at:s.generated_at,dimensions,entities},null,2)+'\n');
await write('data/exports/entities.csv',csv);
await write('docs/data/entities.json',JSON.stringify(entities));
await write('docs/data/statistics.json',JSON.stringify(s,null,2));
await write('docs/data/definitions.json',JSON.stringify(definitions,null,2));
await write('docs/data/taxonomy.json',JSON.stringify(semantic,null,2));
await write('docs/data/entities.csv',csv);
await write('data/exports/intelligence.json',JSON.stringify(intelligence,null,2)+'\n');
await write('data/exports/market-maps.json',JSON.stringify({dataset_version:DATASET_VERSION,calculated_at:CALCULATED_AT,market_maps:intelligence.market_maps},null,2)+'\n');
await write('data/exports/comparisons.json',JSON.stringify({dataset_version:DATASET_VERSION,calculated_at:CALCULATED_AT,comparisons:intelligence.comparisons},null,2)+'\n');
await write('data/exports/benchmarks.json',JSON.stringify({dataset_version:DATASET_VERSION,calculated_at:CALCULATED_AT,benchmarks:intelligence.benchmarks},null,2)+'\n');
await write('data/exports/data-quality.json',JSON.stringify(intelligence.benchmarks.find(item=>item.id==='data-quality'),null,2)+'\n');
await write('docs/data/intelligence.json',JSON.stringify(intelligence,null,2));
await write('docs/data/market-maps.json',JSON.stringify(intelligence.market_maps,null,2));
await write('docs/data/comparisons.json',JSON.stringify(intelligence.comparisons,null,2));
await write('docs/data/benchmarks.json',JSON.stringify(intelligence.benchmarks,null,2));
await write('docs/data/data-quality.json',JSON.stringify(intelligence.benchmarks.find(item=>item.id==='data-quality'),null,2));
const factExport=entities.flatMap(entity=>entity.facts.map(fact=>({...fact,entity_id:entity.id})));
const graphExport={dataset_version:DATASET_VERSION,schema_version:SCHEMA_VERSION,generated_at:CALCULATED_AT,entities, facts:factExport,relationships:knowledgeGraph.relationships,sources:sourceRegistry,taxonomy:{core:taxonomy,semantic},definitions};
await write('data/exports/sources.json',JSON.stringify({dataset_version:DATASET_VERSION,schema_version:'1.0.0',sources:sourceRegistry},null,2)+'\n');
await write('data/exports/facts.json',JSON.stringify({dataset_version:DATASET_VERSION,schema_version:SCHEMA_VERSION,facts:factExport},null,2)+'\n');
await write('data/exports/relationships.json',JSON.stringify(knowledgeGraph,null,2)+'\n');
await write('data/exports/knowledge-graph.json',JSON.stringify(graphExport,null,2)+'\n');
await write('docs/data/sources.json',JSON.stringify(sourceRegistry));
await write('docs/data/facts.json',JSON.stringify(factExport));
await write('docs/data/relationships.json',JSON.stringify(knowledgeGraph));
await write('docs/data/knowledge-graph.json',JSON.stringify(graphExport));
await write('docs/data/search-index.json',JSON.stringify(entities.map(entity=>({id:entity.id,name:entity.name,slug:entity.slug,aliases:entity.aliases||[],categories:entity.categories,cxo_roles:entity.cxo_roles}))));

const depth=title=>/^(Entity:|Guide:|Provider:|Format:|Intelligence:|Industry:)/.test(title)||['Intelligence Home','Providers Home','Industries Home'].includes(title)?'../':'';
const canonicalPath=title=>title==='Home'?'':title==='Intelligence Home'?'intelligence/':title==='Providers Home'?'providers/':title==='Industries Home'?'industries/':title.startsWith('Entity:')?`entities/${slug(title.slice(7))}.html`:title.startsWith('Guide:')?`guides/${slug(title.slice(6))}.html`:title.startsWith('Provider:')?`providers/${slug(title.slice(9))}.html`:title.startsWith('Format:')?`formats/${slug(title.slice(7))}.html`:title.startsWith('Intelligence:')?`intelligence/${slug(title.slice(13))}.html`:title.startsWith('Industry:')?`industries/${slug(title.slice(9))}.html`:`${slug(title)}.html`;
const shell=(title,body,description='Open-source intelligence for the C-suite.',pageTitle=title)=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(pageTitle)} | CXO Ecosystem Index</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="https://openfutureforum.github.io/cxo-ecosystem-index/${canonicalPath(title)}"><meta property="og:title" content="${esc(pageTitle)} | CXO Ecosystem Index"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><link rel="stylesheet" href="${depth(title)}assets/style.css"></head><body><header><a class="brand" href="${depth(title)}index.html"><b>CXO</b> Ecosystem Index</a><nav><a href="${depth(title)}index.html#explore">Explore</a><a href="${depth(title)}cxo-ecosystems.html">CXO Ecosystems</a><a href="${depth(title)}providers/index.html">Providers</a><a href="${depth(title)}intelligence/index.html">Intelligence</a><a href="${depth(title)}cfo-guides.html">Research</a><a href="${depth(title)}data.html">Data</a><a href="${depth(title)}methodology.html">Methodology</a></nav></header><main>${body}</main><footer><p>Independent structured index maintained by Open Future Forum. Inclusion does not imply endorsement.</p><p><a href="https://openfutureforum.github.io/executive-communities-index/">Executive Communities Index</a> · <a href="https://openfutureforum.github.io/executive-community-playbook/">Executive Community Playbook</a></p></footer></body></html>`;

const entityCard=entity=>`<article class="card" data-name="${esc(entity.name.toLowerCase())}" data-cxo="${esc(entity.cxo_roles.join('|'))}" data-provider="${esc(entity.provider_types.join('|'))}" data-format="${esc([...entity.community_formats,...entity.event_formats].join('|'))}" data-topic="${esc(entity.topics.join('|'))}" data-need="${esc(entity.executive_needs.join('|'))}" data-geo="${esc(entity.geographies.join('|'))}"><div class="eyebrow">${esc(entity.entity_type)}</div><h3><a href="entities/${entity.slug}.html">${esc(entity.name)}</a></h3><p>${esc(entity.description)}</p><div class="tags">${entity.cxo_roles.slice(0,4).map(x=>`<span>${esc(x)}</span>`).join('')}</div><small>${esc(entity.categories.join(' · '))}</small></article>`;
const entityCards=entities.map(entityCard).join('');
const statCards=Object.entries({Organizations:s.entities,'Sourced facts':s.sourced_facts,'Verified entities':s.verified_entities,'CXO functions':s.cxo_functions,'Provider categories':s.provider_categories,'Geographic markets':s.geographies}).map(([key,value])=>`<div><strong>${value}</strong><span>${key}</span></div>`).join('');
const select=(label,id,options)=>`<label>${label}<select id="${id}"><option value="">All</option>${options.map(x=>`<option value="${esc(typeof x==='string'?x:x.id)}">${esc(typeof x==='string'?x:x.label)}</option>`).join('')}</select></label>`;

const groupByTerm=(field,minimum)=>Object.entries(Object.groupBy(entities.flatMap(entity=>entity[field].map(id=>({id,entity}))),item=>item.id)).map(([id,items])=>({id,entities:items.map(item=>item.entity)})).filter(group=>group.entities.length>=minimum).sort((a,b)=>b.entities.length-a.entities.length||a.id.localeCompare(b.id));
const providerGroups=groupByTerm('provider_types',4);
const formatGroups=groupByTerm('community_formats',3);
const termTitle=id=>id.split('-').map(word=>({ai:'AI',cfo:'CFO',hr:'HR',m:'M'}[word]||word[0].toUpperCase()+word.slice(1))).join(' ').replace('M A','M&A');
const browseLinks=[...providerGroups.map(group=>`<a href="providers/${group.id}.html">${esc(termTitle(group.id))} <small>${group.entities.length}</small></a>`),...formatGroups.map(group=>`<a href="formats/${group.id}.html">${esc(vocab.get(`community_formats:${group.id}`)?.label||termTitle(group.id))} <small>${group.entities.length}</small></a>`)].join('');

const home=`<section class="hero"><div class="eyebrow">OPEN-SOURCE C-SUITE INTELLIGENCE</div><h1>CXO Ecosystem Index</h1><p>Structured intelligence on who serves executives, which formats they offer, what intelligence they publish, which needs they address, and where they operate.</p><div class="actions"><a href="#explore">Explore the index</a><a class="secondary" href="data.html">Download data</a></div></section><section class="stats">${statCards}</section><section id="explore"><div class="section-head"><div><div class="eyebrow">CANONICAL ENTITY INDEX</div><h2>Explore the ecosystem</h2></div><p>Filter one canonical dataset. Filter combinations are application state, not automatically generated SEO pages.</p></div><div class="filters expanded"><label>Search<input id="search" type="search" placeholder="Name, type, format, topic, or need"></label>${select('CXO role','cxo',taxonomy.cxo_roles)}${select('Provider type','provider',taxonomy.categories.map(x=>({id:slug(x),label:x})))}${select('Format','format',[...semantic.community_formats,...semantic.event_formats])}${select('Topic','topic',semantic.topics)}${select('Executive need','need',semantic.executive_needs)}${select('Geography','geo',taxonomy.geographies)}</div><p id="result-count" class="count"></p><div id="grid" class="grid">${entityCards}</div></section><section class="principles"><div><div class="eyebrow">CONTROLLED MODEL</div><h2>Explicit relationships, visible evidence.</h2></div><ol><li><b>Canonical records</b><span>One entity can serve multiple roles, formats, topics, and needs without duplicate pages.</span></li><li><b>Controlled terms</b><span>Stable IDs and neutral definitions prevent synonym drift.</span></li><li><b>Evidence</b><span>Entity associations require official or reputable support.</span></li></ol></section><script src="assets/app.js"></script>`;
const intelligenceLinks=intelligence.market_maps.slice(0,4).map(item=>`<a href="intelligence/${item.id}.html">${esc(item.title)}</a>`).join('');
const homeWithBrowse=home.replace('<section id="explore">',`<section class="prose wide"><div class="eyebrow">DATA + INTELLIGENCE</div><h2>What does the dataset tell us?</h2><p>Explore reproducible market maps, comparisons, benchmarks and data-quality analysis generated from canonical records.</p><div class="download"><a href="intelligence/index.html">Intelligence Home</a>${intelligenceLinks}<a href="data-quality.html">Data Quality</a></div><h2>Browse established provider categories</h2><p>Only substantial cohorts with distinct intent, structured statistics and source coverage receive canonical pages. More specific combinations remain filters.</p><div class="download">${browseLinks}</div></section><section id="explore">`);
await write('docs/index.html',shell('Home',homeWithBrowse));

for(const entity of entities){
 const facts=[['Organization type',entity.entity_type],['Common names / aliases',(entity.aliases||[]).join(', ')],['Parent company',entity.parent_company],['Relationship notes',entity.relationship_notes],['Editorial research priority',entity.editorial_priority],['Serves',entity.cxo_roles.join(', ')],['Provider categories',entity.categories.join(', ')],['Industries',(entity.industries||[]).join(', ')],['Geography',entity.geographies.join(', ')],['Verification',entity.verification_status],['Last verified',entity.last_verified]].filter(([,value])=>value);
 const sections=[['Community formats',labels('community_formats',entity.community_formats)],['Event formats',labels('event_formats',entity.event_formats)],['Research & intelligence',labels('intelligence_types',entity.intelligence_types)],['Resources',labels('resource_types',entity.resource_types)],['Executive needs',labels('executive_needs',entity.executive_needs)],['Topics',labels('topics',entity.topics)],['Additional audiences',labels('audiences',entity.audiences)]];
 const semanticSections=sections.filter(([,values])=>values.length).map(([heading,values])=>`<section><h2>${heading}</h2><div class="tags large">${values.map(value=>`<span>${esc(value)}</span>`).join('')}</div></section>`).join('');
 const sources=[...entity.sources.map(x=>({id:x.id,url:x.url,title:x.title,detail:`${x.publisher} · accessed ${x.accessed_date} · supports ${x.supports.join(', ')}`})),...entity.classification_evidence.map((x,index)=>({id:`classification-source-${index+1}`,url:x.url,title:x.title,detail:`classification evidence · supports ${x.supports.join(', ')}`}))];
 const sourceList=sources.map(source=>`<li id="${esc(source.id||'classification-source')}"><a href="${esc(source.url)}">${esc(source.title)}</a><span>${esc(source.detail)}</span></li>`).join('');
 const factRows=(entity.facts||[]).map(fact=>`<tr><td>${esc(fact.field.replaceAll('_',' '))}</td><td>${esc(factDisplay(fact))}</td><td>${fact.source_ids.map(id=>`<a href="#${esc(id)}">${esc(id)}</a>`).join(', ')}</td><td>${esc(fact.as_of_date||fact.last_verified)}</td></tr>`).join('');
 const relationRows=(relationsBySubject[entity.id]||[]).map(relation=>{const related=byId.get(relation.object_entity_id);return `<tr><td>${esc(relation.predicate.replaceAll('_',' '))}</td><td><a href="${related.slug}.html">${esc(related.name)}</a></td><td>${esc(relation.status)}</td><td>${esc(relation.as_of_date||relation.valid_from||'')}</td><td>${esc(relation.source_ids.join(', '))}${relation.derived_reciprocal?' · reciprocal derived from sourced edge':''}</td></tr>`;}).join('');
 const jsonld=JSON.stringify({'@context':'https://schema.org','@type':'Organization',name:entity.name,alternateName:entity.aliases||[],url:entity.website,description:entity.description,areaServed:entity.geographies,knowsAbout:labels('topics',entity.topics).length?labels('topics',entity.topics):entity.categories,parentOrganization:entity.parent_company?{'@type':'Organization',name:entity.parent_company}:undefined});
 const body=`<nav class="crumb"><a href="../index.html">Index</a> / ${esc(entity.name)}</nav><section class="entity-head"><div class="eyebrow">${esc(entity.entity_type)}</div><h1>${esc(entity.name)}</h1><p>${esc(entity.description)}</p><a class="site-link" href="${esc(entity.website)}">Official website ↗</a></section><section class="entity-layout"><div><h2>Structured facts</h2><dl>${facts.map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join('')}</dl></div><div><h2>Inclusion basis</h2><p>${esc(entity.inclusion_basis.join(' '))}</p><h2>Products and services</h2><p>${esc([...(entity.products||[]),...(entity.services||[])].join(', ')||'Not recorded.')}</p></div></section><div class="semantic-sections">${semanticSections}</div><section><h2>Source-linked facts</h2><p>${entity.facts.length} structured facts are linked to the supporting source record and verification or as-of date.</p><div class="table-wrap"><table><thead><tr><th>Field</th><th>Value</th><th>Source ID</th><th>As of / verified</th></tr></thead><tbody>${factRows}</tbody></table></div></section>${relationRows?`<section><h2>Ecosystem Relationships</h2><div class="table-wrap"><table><thead><tr><th>Relationship</th><th>Organization</th><th>Status</th><th>Date</th><th>Provenance</th></tr></thead><tbody>${relationRows}</tbody></table></div></section>`:''}<section><h2>Sources</h2><ul class="sources">${sourceList}</ul></section><script type="application/ld+json">${jsonld}</script>`;
 await write(`docs/entities/${entity.slug}.html`,shell(`Entity: ${entity.name}`,body,entity.description,`${entity.name} | ${entity.categories.slice(0,2).join(' & ')}`));
}

const cfoEntities=entities.filter(entity=>entity.cxo_roles.includes('CFO'));
const topicList=items=>`<div class="topic-grid">${items.map(item=>`<span>${esc(typeof item==='string'?item:item.name)}</span>`).join('')}</div>`;
await write('docs/cfo-ecosystem.html',shell('CFO Ecosystem',`<section class="prose wide"><div class="eyebrow">EXPLORE BY CXO</div><h1>CFO Ecosystem</h1><p>A structured view of the companies, advisors, capital providers, communities, and technology platforms serving chief financial officers and finance organizations.</p><div class="stats compact"><div><strong>${cfoEntities.length}</strong><span>CFO-relevant entities</span></div><div><strong>${new Set(cfoEntities.flatMap(e=>e.categories)).size}</strong><span>Provider categories</span></div><div><strong>${new Set(cfoEntities.flatMap(e=>e.geographies)).size}</strong><span>Markets represented</span></div></div><h2>Operating contexts</h2>${topicList(cfoTaxonomy.contexts)}<h2>Finance functions</h2>${topicList(cfoTaxonomy.functional_topics)}<h2>Systems and transformation</h2>${topicList(cfoTaxonomy.systems_topics)}<h2>Decision resources</h2>${topicList(cfoTaxonomy.decision_resources)}<h2>Indexed organizations</h2><div class="grid">${cfoEntities.map(entityCard).join('')}</div></section>`,'Structured intelligence on providers, systems, capital, communities, and advisors serving CFOs.'));
const rolePages=[
 {label:'CEO',roles:['CEO'],description:'Chief executives responsible for enterprise strategy, leadership, capital, growth, and board accountability.'},
 {label:'CMO',roles:['CMO'],description:'Chief marketing officers responsible for market strategy, customer acquisition, brand, growth, and marketing performance.'},
 {label:'CISO',roles:['CISO'],description:'Chief information security officers responsible for cybersecurity strategy, identity, risk, resilience, and board reporting.'},
 {label:'CIO & CTO',roles:['CIO','CTO'],description:'Technology executives responsible for enterprise systems, data, artificial intelligence, architecture, engineering, and technology strategy.'},
 {label:'CHRO',roles:['CHRO'],description:'People executives responsible for workforce strategy, talent, human resources, benefits, performance, and organizational development.'},
 {label:'CLO & General Counsel',roles:['CLO','General Counsel'],description:'Senior legal executives responsible for corporate law, governance, transactions, regulation, disputes, privacy, and legal operations.'},
 {label:'COO',roles:['COO'],description:'Operating executives responsible for organizational execution, processes, systems, delivery, and performance.'},
 {label:'Board',roles:['Board'],description:'Board directors and governance leaders responsible for oversight, accountability, succession, risk, and long-term enterprise stewardship.'}
];
for(const group of rolePages){const roleEntities=entities.filter(entity=>group.roles.some(role=>entity.cxo_roles.includes(role)));const roleSlug=slug(group.label);await write(`docs/${roleSlug}-ecosystem.html`,shell(`${group.label} Ecosystem`,`<section class="prose wide"><div class="eyebrow">EXPLORE BY CXO</div><h1>${group.label} Ecosystem</h1><p>${esc(group.description)}</p><p>This canonical role page contains ${roleEntities.length} evidence-backed organizations across ${new Set(roleEntities.flatMap(e=>e.categories)).size} provider categories. Related titles are normalized into one functional hub where appropriate.</p><div class="grid">${roleEntities.map(entityCard).join('')}</div></section>`,`Structured index of organizations serving ${group.label} leaders.`));}
const roleLinks=[{label:'CFO',href:'cfo-ecosystem.html',count:cfoEntities.length},...rolePages.map(group=>({label:group.label,href:`${slug(group.label)}-ecosystem.html`,count:entities.filter(entity=>group.roles.some(role=>entity.cxo_roles.includes(role))).length}))];
await write('docs/cxo-ecosystems.html',shell('CXO Ecosystems',`<section class="prose wide"><div class="eyebrow">FUNCTIONAL ECOSYSTEMS</div><h1>CXO Ecosystems</h1><p>Browse evidence-backed provider landscapes by executive function. CLO and General Counsel are normalized into one legal-leadership ecosystem; CIO and CTO share one technology-leadership ecosystem.</p><div class="grid">${roleLinks.map(item=>`<article class="card"><h3><a href="${item.href}">${esc(item.label)} Ecosystem</a></h3><p>${item.count} indexed organizations.</p></article>`).join('')}</div></section>`,'Evidence-backed provider ecosystems for executive functions.'));

for(const group of providerGroups){
 const label=termTitle(group.id);const roles=[...new Set(group.entities.flatMap(entity=>entity.cxo_roles))];const markets=[...new Set(group.entities.flatMap(entity=>entity.geographies))];
 const primaryCount=group.entities.filter(entity=>entity.sources.some(source=>['official company','official organization','government','regulatory','investor relations'].includes(source.source_class))).length;
 const aiCount=group.entities.filter(entity=>entity.categories.some(category=>['Artificial Intelligence','AI Agents','AI Infrastructure','AI Security'].includes(category))).length;
 const roleCounts=Object.entries(Object.groupBy(group.entities.flatMap(entity=>entity.cxo_roles),role=>role)).map(([role,items])=>[role,items.length]).sort((a,b)=>b[1]-a[1]);
 const subcategoryCounts=Object.entries(Object.groupBy(group.entities.flatMap(entity=>entity.categories.filter(category=>slug(category)!==group.id)),category=>category)).map(([category,items])=>[category,items.length]).sort((a,b)=>b[1]-a[1]).slice(0,8);
 const body=`<section class="prose wide"><div class="eyebrow">PROVIDER TYPE</div><h1>${esc(label)}</h1><p>An evidence-backed view of organizations classified as ${esc(label.toLowerCase())} providers in the CXO Ecosystem Index.</p><div class="stats compact"><div><strong>${group.entities.length}</strong><span>Organizations</span></div><div><strong>${Math.round(100*primaryCount/group.entities.length)}%</strong><span>Primary-source coverage</span></div><div><strong>${aiCount}</strong><span>AI-related providers</span></div></div><h2>Category intelligence</h2><p><b>CXO-role distribution:</b> ${roleCounts.map(([role,count])=>`${esc(role)} ${count}`).join(' · ')}</p><p><b>Common adjacent categories:</b> ${subcategoryCounts.map(([category,count])=>`${esc(category)} ${count}`).join(' · ')||'No adjacent category recorded.'}</p><p><small>Statistics use dataset version ${DATASET_VERSION}, calculation date ${CALCULATED_AT}, and all ${group.entities.length} indexed organizations in this category as the denominator. Unknown fields are not inferred.</small></p><h2>Indexed organizations</h2><div class="grid">${group.entities.map(entityCard).join('').replaceAll('href="entities/','href="../entities/')}</div><p><small>Inclusion is neutral and does not imply endorsement. Category membership requires cited evidence on each organization page.</small></p></section>`;
 await write(`docs/providers/${group.id}.html`,shell(`Provider: ${label}`,body,`Evidence-backed index of ${label.toLowerCase()} organizations serving executives.`));
}
for(const group of formatGroups){
 const term=vocab.get(`community_formats:${group.id}`);const label=term?.label||termTitle(group.id);
 const body=`<section class="prose wide"><div class="eyebrow">COMMUNITY FORMAT</div><h1>${esc(label)}</h1><p>${esc(term?.definition||`Organizations offering the ${label.toLowerCase()} format.`)}</p><p>This canonical format page includes ${group.entities.length} evidence-backed organizations. Narrower role, topic, need, and geography combinations remain filters.</p><h2>Indexed organizations</h2><div class="grid">${group.entities.map(entityCard).join('').replaceAll('href="entities/','href="../entities/')}</div><p><small>Format classification requires cited evidence on each organization page.</small></p></section>`;
 await write(`docs/formats/${group.id}.html`,shell(`Format: ${label}`,body,`Organizations offering the ${label.toLowerCase()} format.`));
}

const providerHubCards=providerGroups.map(group=>`<article class="card"><h3><a href="${group.id}.html">${esc(termTitle(group.id))}</a></h3><p>${group.entities.length} indexed organizations with reproducible category statistics.</p></article>`).join('');
await write('docs/providers/index.html',shell('Providers Home',`<section class="prose wide"><div class="eyebrow">PROVIDER DISCOVERY</div><h1>Provider Intelligence</h1><p>Substantial provider cohorts with source coverage, CXO-role distribution, adjacent-category analysis, and canonical entity records.</p><div class="grid">${providerHubCards}</div></section>`,'Provider intelligence across the C-suite ecosystem.','Providers'));

